/*
 * make-track.mjs — renders the demo tracks from scratch.
 *
 * Why synthesize instead of downloading tracks? Licensing. Self-made audio is
 * 100% ours, needs no attribution, and can never cause a takedown. It also makes
 * a nice portfolio talking point: the audio is generated by code, too.
 *
 * Usage:  npm run make-track              → renders every preset
 *         node scripts/make-track.mjs low-tide   → renders one
 * Output: public/audio/<name>.mp3 (needs ffmpeg on the PATH; the WAV is kept
 *         next to it and git-ignored).
 *
 * How it works, in one paragraph: audio is just a long list of numbers (samples),
 * 44,100 of them per second per channel. Each instrument below is a tiny function
 * that adds its samples into two big arrays (left + right). At the end we soft-clip,
 * normalise, and write a WAV file, which ffmpeg turns into a small MP3.
 */

import { writeFileSync, mkdirSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import path from "node:path";

const SR = 44100; // sample rate (samples per second)
const midi = (n) => 440 * 2 ** ((n - 69) / 12); // MIDI note number → Hz

/*
 * One preset per track. `chords` = 2 bars each, cycling. `roots` are the bass
 * notes (MIDI). The arrangement functions say which instrument plays in which
 * bar, so each track has its own build-up without a separate script.
 */
const PRESETS = {
  // The lead single: 32 bars, A minor, full arrangement with a breakdown.
  afterglow: {
    bpm: 124,
    bars: 32,
    seed: 1234567,
    chords: [
      { root: 33, notes: [57, 60, 64, 67] }, // Am7
      { root: 29, notes: [57, 60, 65, 69] }, // Fmaj7
      { root: 36, notes: [55, 60, 64, 67] }, // C
      { root: 31, notes: [55, 59, 62, 67] }, // G
    ],
    kick: (b) => (b >= 8 && b < 24) || b >= 28,
    clap: (b) => (b >= 16 && b < 24) || b >= 28,
    hats: (b) => b >= 4,
    bass: (b) => b >= 8,
    stab: (b) => (b >= 16 && b < 24) || b >= 28,
    isBreak: (b) => b >= 24 && b < 28,
    padOpen: (b) => Math.min(1, b / 12),
    arpLevel: (b) => Math.min(1, (b + 1) / 6),
    risers: [
      [6, 2],
      [24, 4],
    ],
    pickupKick: 8, // a lone kick one beat before this bar
    busyHatsFrom: 12,
  },
  // Slower, dubbier: D minor, the kick arrives early and never leaves.
  "low-tide": {
    bpm: 118,
    bars: 16,
    seed: 42,
    chords: [
      { root: 26, notes: [50, 53, 57, 60] }, // Dm7
      { root: 22, notes: [50, 53, 58, 62] }, // Bbmaj7
      { root: 29, notes: [48, 53, 57, 60] }, // F
      { root: 24, notes: [48, 52, 55, 60] }, // C
    ],
    kick: (b) => b >= 4,
    clap: (b) => b >= 8,
    hats: () => true,
    bass: (b) => b >= 4,
    stab: () => false,
    isBreak: () => false,
    padOpen: (b) => Math.min(1, (b + 2) / 8),
    arpLevel: (b) => 0.6 * Math.min(1, (b + 1) / 4),
    risers: [[2, 2]],
    pickupKick: 4,
    busyHatsFrom: 99,
  },
  // Faster and brighter: F minor, stabs from the start of the second half.
  "neon-rain": {
    bpm: 128,
    bars: 16,
    seed: 777,
    chords: [
      { root: 29, notes: [53, 56, 60, 63] }, // Fm7
      { root: 25, notes: [53, 56, 61, 65] }, // Db
      { root: 32, notes: [56, 60, 63, 68] }, // Ab
      { root: 27, notes: [55, 58, 63, 67] }, // Eb
    ],
    kick: (b) => b >= 2,
    clap: (b) => b >= 4,
    hats: () => true,
    bass: (b) => b >= 2,
    stab: (b) => b >= 8,
    isBreak: () => false,
    padOpen: (b) => Math.min(1, (b + 4) / 8),
    arpLevel: () => 1,
    risers: [[6, 2]],
    pickupKick: 2,
    busyHatsFrom: 4,
  },
  // Slow and sparse: E minor, half the track is pad + arp before the drums land.
  "signal-fade": {
    bpm: 110,
    bars: 16,
    seed: 99,
    chords: [
      { root: 28, notes: [52, 55, 59, 62] }, // Em7
      { root: 24, notes: [52, 55, 60, 64] }, // Cmaj7
      { root: 31, notes: [50, 55, 59, 62] }, // G
      { root: 26, notes: [50, 54, 57, 62] }, // D
    ],
    kick: (b) => b >= 8,
    clap: () => false,
    hats: (b) => b >= 4,
    bass: (b) => b >= 8,
    stab: () => false,
    isBreak: () => false,
    padOpen: (b) => Math.min(1, (b + 3) / 10),
    arpLevel: (b) => 0.8 * Math.min(1, (b + 1) / 6),
    risers: [[6, 2]],
    pickupKick: 8,
    busyHatsFrom: 12,
  },
};

function render(name, P) {
  const BEAT = (SR * 60) / P.bpm; // samples per beat
  const BAR = BEAT * 4;
  const TOTAL = Math.round(BAR * P.bars);
  const L = new Float64Array(TOTAL);
  const R = new Float64Array(TOTAL);

  // Deterministic random numbers, so the file is identical on every run.
  let seed = P.seed;
  const rand = () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const noise = () => rand() * 2 - 1;

  const add = (i, l, r) => {
    if (i >= 0 && i < TOTAL) {
      L[i] += l;
      R[i] += r;
    }
  };

  // One-pole low-pass filter: a cheap "dull it down" effect. `coef` 0–1 sets the cutoff.
  const lpCoef = (hz) => 1 - Math.exp((-2 * Math.PI * hz) / SR);
  const lowpass = () => {
    let y = 0;
    return (x, coef) => (y += coef * (x - y));
  };

  const chordAt = (bar) => P.chords[Math.floor(bar / 2) % P.chords.length];

  /* ---------- Sidechain "duck": everything dips for ~150ms after each kick ----------
   * This is THE classic electronic-music pumping effect, and it's also what makes
   * the visual feel locked to the beat: the bass band in the analyser spikes on
   * every kick and relaxes in between. */
  const duck = new Float64Array(TOTAL).fill(1);
  for (let bar = 0; bar < P.bars; bar++) {
    if (!P.kick(bar)) continue;
    for (let beat = 0; beat < 4; beat++) {
      const start = Math.round(bar * BAR + beat * BEAT);
      for (let i = 0; i < SR * 0.4; i++) {
        const t = i / SR;
        const v = 1 - 0.8 * Math.exp(-t / 0.14);
        if (start + i < TOTAL) duck[start + i] = Math.min(duck[start + i], v);
      }
    }
  }

  /* ---------- Drums ---------- */
  function kick(start, vel = 1) {
    const len = Math.floor(0.45 * SR);
    let phase = 0;
    for (let i = 0; i < len; i++) {
      const t = i / SR;
      const freq = 46 + 120 * Math.exp(-t / 0.04); // pitch drops fast: the "thump"
      phase += (2 * Math.PI * freq) / SR;
      const body = Math.sin(phase) * Math.exp(-t / 0.16);
      const click = noise() * Math.exp(-t / 0.003) * 0.5;
      const s = Math.tanh((body + click) * 1.6) * 0.95 * vel;
      add(start + i, s, s);
    }
  }

  function clap(start, vel = 1) {
    const lp = lowpass();
    const lp2 = lowpass();
    const len = Math.floor(0.3 * SR);
    for (let i = 0; i < len; i++) {
      const t = i / SR;
      const burst = t < 0.03 ? 1 : Math.exp(-(t - 0.03) / 0.07) * 0.8; // bursts, then a tail
      const n = noise();
      const band = lp(n, lpCoef(5000)) - lp2(n, lpCoef(900)); // band-pass-ish
      const s = band * burst * 0.55 * vel;
      add(start + i, s * 0.9, s * 1.0);
    }
  }

  function hat(start, open = false, vel = 1) {
    const lp = lowpass();
    const decay = open ? 0.22 : 0.045;
    const len = Math.floor(decay * 6 * SR);
    for (let i = 0; i < len; i++) {
      const t = i / SR;
      const n = noise();
      const high = n - lp(n, lpCoef(7000)); // remove lows = crisp hi-hat
      const s = high * Math.exp(-t / decay) * (open ? 0.22 : 0.17) * vel;
      add(start + i, s * 0.8, s * 1.05); // slightly right of centre
    }
  }

  /* ---------- Bass: filtered saw, syncopated 16ths, ducked by the kick ---------- */
  const BASS_STEPS = [0, 2, 3, 6, 8, 10, 11, 14]; // which 16th notes play (0–15)
  function bass(bar) {
    const f = midi(chordAt(bar).root);
    for (const step of BASS_STEPS) {
      const start = Math.round(bar * BAR + (step * BEAT) / 4);
      const len = Math.floor((BEAT / 4) * 0.85);
      const lp = lowpass();
      const lp2 = lowpass();
      let phase = 0;
      const brightness = P.isBreak(bar) ? 0.4 : 1;
      for (let i = 0; i < len; i++) {
        const t = i / SR;
        phase = (phase + f / SR) % 1;
        const saw = phase * 2 - 1;
        const env = Math.min(1, t / 0.004) * Math.exp(-t / 0.25);
        const cutoff = (160 + 900 * Math.exp(-t / 0.08)) * brightness;
        const s = lp2(lp(saw, lpCoef(cutoff)), lpCoef(cutoff)) * env * 0.75 * duck[start + i];
        add(start + i, s, s);
      }
    }
  }

  /* ---------- Pad: detuned saws, filter slowly opening through the intro ---------- */
  function pad(bar) {
    const chord = chordAt(bar);
    const start = Math.round(bar * BAR);
    const len = Math.round(BAR);
    const openness = P.padOpen(bar) * (P.isBreak(bar) ? 1.2 : 1);
    const fadeIn = bar % 2 === 0 ? 0.25 : 0; // seconds; chords change every 2 bars
    const fadeOut = bar % 2 === 1 ? 0.25 : 0;
    chord.notes.forEach((note) => {
      [-8, 0, 8].forEach((cents, v) => {
        const f = midi(note) * 2 ** (cents / 1200);
        const lp = lowpass();
        const lp2 = lowpass();
        let phase = rand();
        const panL = v === 0 ? 1 : v === 1 ? 0.7 : 0.35;
        const panR = v === 2 ? 1 : v === 1 ? 0.7 : 0.35;
        for (let i = 0; i < len; i++) {
          const t = i / SR;
          phase = (phase + f / SR) % 1;
          const saw = phase * 2 - 1;
          let env = 1;
          if (fadeIn) env *= Math.min(1, t / fadeIn);
          if (fadeOut) env *= Math.min(1, (len - i) / SR / fadeOut);
          const lfo = 0.5 + 0.5 * Math.sin((2 * Math.PI * 0.07 * (start + i)) / SR);
          const cutoff = 250 + (400 + 1600 * lfo) * openness;
          const s = lp2(lp(saw, lpCoef(cutoff)), lpCoef(cutoff)) * env * 0.055 * (0.4 + 0.6 * duck[start + i]);
          add(start + i, s * panL, s * panR);
        }
      });
    });
  }

  /* ---------- Arp: plucky 16th notes walking up and down the chord ---------- */
  const arpL = new Float64Array(TOTAL);
  const arpR = new Float64Array(TOTAL);
  const ARP_PATTERN = [0, 1, 2, 3, 2, 1, 0, 2];
  function arp(bar) {
    const chord = chordAt(bar);
    const level = P.arpLevel(bar) * (P.stab(bar) ? 0.8 : 1);
    for (let step = 0; step < 16; step++) {
      const idx = ARP_PATTERN[(bar * 16 + step) % ARP_PATTERN.length];
      const octave = step % 4 === 2 ? 24 : 12;
      const f = midi(chord.notes[idx] + octave);
      const start = Math.round(bar * BAR + (step * BEAT) / 4);
      const len = Math.floor(0.3 * SR);
      const lp = lowpass();
      let phase = 0;
      for (let i = 0; i < len; i++) {
        const t = i / SR;
        phase = (phase + f / SR) % 1;
        const tri = 1 - 4 * Math.abs(phase - 0.5); // triangle wave: soft and round
        const sq = phase < 0.5 ? 1 : -1;
        const env = Math.min(1, t / 0.002) * Math.exp(-t / 0.09);
        const s = lp(tri * 0.7 + sq * 0.3, lpCoef(2500 + 3000 * Math.exp(-t / 0.05))) * env * 0.16 * level;
        if (start + i < TOTAL) {
          arpL[start + i] += s;
          arpR[start + i] += s;
        }
      }
    }
  }

  /* ---------- Stab: off-beat chord hits (classic house) ---------- */
  function stab(bar) {
    const chord = chordAt(bar);
    for (let beat = 0; beat < 4; beat++) {
      const start = Math.round(bar * BAR + beat * BEAT + BEAT / 2); // the "and" of each beat
      const len = Math.floor(0.22 * SR);
      chord.notes.forEach((note, n) => {
        const f = midi(note + 12);
        const lp = lowpass();
        let phase = rand();
        for (let i = 0; i < len; i++) {
          const t = i / SR;
          phase = (phase + f / SR) % 1;
          const saw = phase * 2 - 1;
          const env = Math.min(1, t / 0.003) * Math.exp(-t / 0.07);
          const s = lp(saw, lpCoef(1200 + 2500 * Math.exp(-t / 0.04))) * env * 0.09;
          add(start + i, s * (n % 2 ? 1 : 0.6), s * (n % 2 ? 0.6 : 1));
        }
      });
    }
  }

  /* ---------- Riser: noise sweeping up into a drop ---------- */
  function riser(fromBar, bars) {
    const start = Math.round(fromBar * BAR);
    const len = Math.round(bars * BAR);
    const lp = lowpass();
    for (let i = 0; i < len; i++) {
      const p = i / len; // 0 → 1 across the riser
      const cutoff = 150 + 9000 * p * p;
      const s = lp(noise(), lpCoef(cutoff)) * p * p * 0.35;
      add(start + i, s * (1 - p * 0.3), s * (0.7 + p * 0.3));
    }
  }

  /* ---------- Render the arrangement ---------- */
  for (let bar = 0; bar < P.bars; bar++) {
    pad(bar);
    arp(bar);
    if (P.bass(bar)) bass(bar);
    if (P.stab(bar)) stab(bar);
    for (let beat = 0; beat < 4; beat++) {
      const b = Math.round(bar * BAR + beat * BEAT);
      if (P.kick(bar)) kick(b);
      if (P.clap(bar) && beat % 2 === 1) clap(b);
      if (P.hats(bar)) {
        hat(b, false, 0.8);
        hat(Math.round(b + BEAT / 2), P.kick(bar), 1); // open hat on the off-beat once the kick is in
        if (bar >= P.busyHatsFrom) {
          hat(Math.round(b + BEAT / 4), false, 0.35);
          hat(Math.round(b + (3 * BEAT) / 4), false, 0.45);
        }
      }
    }
  }
  kick(Math.round(P.pickupKick * BAR - BEAT), 0.8); // pick-up kick before the drop
  for (const [from, bars] of P.risers) riser(from, bars);

  // Arp delay: a dotted-eighth echo bouncing left/right ("ping-pong") = instant width.
  const delaySamples = Math.round((BEAT * 3) / 4);
  for (let i = 0; i < TOTAL; i++) {
    const j = i - delaySamples;
    if (j >= 0) {
      arpL[i] += arpR[j] * 0.42;
      arpR[i] += arpL[j] * 0.42;
    }
    L[i] += arpL[i] * 0.9;
    R[i] += arpR[i] * 1.0;
  }

  /* ---------- Master: soft-clip, normalise, write ---------- */
  let peak = 0;
  for (let i = 0; i < TOTAL; i++) {
    L[i] = Math.tanh(L[i] * 1.1);
    R[i] = Math.tanh(R[i] * 1.1);
    peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i]));
  }
  const gain = 0.95 / peak;

  // WAV = a 44-byte header followed by interleaved 16-bit samples.
  const bytes = Buffer.alloc(44 + TOTAL * 4);
  bytes.write("RIFF", 0);
  bytes.writeUInt32LE(36 + TOTAL * 4, 4);
  bytes.write("WAVE", 8);
  bytes.write("fmt ", 12);
  bytes.writeUInt32LE(16, 16);
  bytes.writeUInt16LE(1, 20); // PCM
  bytes.writeUInt16LE(2, 22); // stereo
  bytes.writeUInt32LE(SR, 24);
  bytes.writeUInt32LE(SR * 4, 28);
  bytes.writeUInt16LE(4, 32);
  bytes.writeUInt16LE(16, 34);
  bytes.write("data", 36);
  bytes.writeUInt32LE(TOTAL * 4, 40);
  for (let i = 0; i < TOTAL; i++) {
    bytes.writeInt16LE(Math.round(L[i] * gain * 32767), 44 + i * 4);
    bytes.writeInt16LE(Math.round(R[i] * gain * 32767), 46 + i * 4);
  }

  const outDir = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "public", "audio");
  mkdirSync(outDir, { recursive: true });
  const wav = path.join(outDir, `${name}.wav`);
  const mp3 = path.join(outDir, `${name}.mp3`);
  writeFileSync(wav, bytes);
  console.log(`${name}: WAV written (${(TOTAL / SR).toFixed(1)}s)`);

  try {
    execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-i", wav, "-codec:a", "libmp3lame", "-b:a", "160k", mp3]);
    console.log(`${name}: MP3 written → ${path.relative(process.cwd(), mp3)}`);
  } catch {
    console.warn(`${name}: ffmpeg not found. The WAV is there; encode it to MP3 yourself.`);
  }
}

const wanted = process.argv.slice(2);
const names = wanted.length ? wanted : Object.keys(PRESETS);
for (const name of names) {
  if (!PRESETS[name]) {
    console.error(`Unknown preset "${name}". Known: ${Object.keys(PRESETS).join(", ")}`);
    process.exit(1);
  }
  render(name, PRESETS[name]);
}
